def add(kind,n,page,note,parts,direct,components=None):
 for p in parts:p.setdefault('response_format','symbolic');p.setdefault('given_representation','text')
 r=h.add(kind,n,page,note,parts,direct);r['component_demand_ids']=components or[]
 r['mapping_rationale']='Map each explicitly requested square form, image, injectivity boundary, composite, inverse and sketch separately. Composition requires inner outputs to lie in the outer domain on the declared full source domain. A restricted-domain extension is distinguished from the source function. Quadratic branch signs follow the actual original interval.'
 if INVERSE in direct or ONEONE in direct:
  r['value_level_scope_decisions']=[{'rule_id':'8227:QUAL08','status':'within','quoted_value':note,'reason':'Use the declared original interval or derive the extremal admissible boundary requested by the item. All inverse formulas retain that branch and its actual image. Printed key omissions/errors are registered separately.'}]
 return r

def square(label,a,b,c,key,kp):
 p=v(label,f'{a}*(x+Rational({b},{2*a}))**2+({c}-Rational({b*b},{4*a}))',key,kp,'Complete the square independently from the ORIGINAL coefficients; retain the requested vertex-form output, not only expanded equality.');p['assessed_8227_demand_ids']=[SQUARE];return p
def inv(label,formula,key,kp,domain,image,method):
 p=v(label,formula,key,kp,method);p.update(assessed_8227_demand_ids=[INVERSE],inverse_domain=domain,inverse_image=image);return p
def bound(label,answer,kp,method):return reasoning(label,answer,method,kp,'matches')
def image(label,func,domain,key,kp):
 p=h.interval_part(label,func,'real-image-range',domain,key,kp,'Independently compute the image of the original expression over the declared interval; check monotonicity, turning-point inclusion and open/closed endpoint attainment.');p['assessed_8227_demand_ids']=[RANGE];return p

